function ForgotPasswordPage() {
  const [email, setEmail] = useState(''); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { const result = await api<{ message: string }>('/auth/forgot-password', json({ email })); setMessage(result.message); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to request a reset link.'); } finally { setBusy(false); } };
  return <AuthFrame title="Reset your password" subtitle="We will send a one-time link to your institutional address."><form className="auth-form" onSubmit={(event) => void submit(event)}>{error ? <Notice tone="danger">{error}</Notice> : null}{message ? <Notice tone="success">{message}</Notice> : null}<label>Institutional email<input value={email} onChange={(event) => setEmail(event.target.value)} type="email" placeholder="you@iiitnr.edu.in" required /></label><button className="button button-primary button-wide" disabled={busy}>{busy ? 'Sending…' : 'Send reset link'}</button></form><p className="auth-switch"><Link to="/login">Back to sign in</Link></p></AuthFrame>;
}

function ResetPasswordPage() {
  const token = new URLSearchParams(window.location.search).get('token') || ''; const [password, setPassword] = useState(''); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { const result = await api<{ message: string }>('/auth/reset-password', json({ token, password })); setMessage(result.message); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to reset the password.'); } finally { setBusy(false); } };
  return <AuthFrame title="Choose a new password" subtitle="Use at least 12 characters. The reset link can only be used once."><form className="auth-form" onSubmit={(event) => void submit(event)}>{error ? <Notice tone="danger">{error}</Notice> : null}{message ? <Notice tone="success">{message} <Link to="/login">Sign in</Link></Notice> : null}<label>New password<input value={password} onChange={(event) => setPassword(event.target.value)} type="password" minLength={12} required /></label><button className="button button-primary button-wide" disabled={busy || !token}>{busy ? 'Saving…' : 'Set new password'}</button>{!token ? <p className="form-note">This link is missing its token. Request a new one.</p> : null}</form><p className="auth-switch"><Link to="/login">Back to sign in</Link></p></AuthFrame>;
}

function VerifyEmailPage() {
  const token = new URLSearchParams(window.location.search).get('token') || ''; const [state, setState] = useState<'ready' | 'working' | 'error'>(token ? 'ready' : 'error'); const [message, setMessage] = useState(token ? 'Click below to verify this institutional email.' : 'This verification link is missing its token.');
  const verify = () => { if (!token) { setState('error'); setMessage('This verification link is missing its token.'); return; } setState('working'); setMessage('Opening the secure verification step…'); window.location.assign(`/api/v1/auth/verify?token=${encodeURIComponent(token)}`); };
  return <AuthFrame title={state === 'error' ? 'Verification link unavailable' : 'Verify your email'} subtitle={message}><div className="auth-form"><Notice tone={state === 'error' ? 'danger' : 'info'}>{message}</Notice><button type="button" className="button button-primary button-wide" disabled={!token || state === 'working'} onClick={verify}>{state === 'working' ? 'Opening…' : 'Verify email'}</button><Link className="button button-secondary button-wide" to="/login">Continue to sign in</Link></div></AuthFrame>;
}

function RootApp() { return <App />; }

function App() {
  return <Routes>
    <Route element={<AuthProvider />}>
      <Route path="/login" element={<Login />} />
      <Route path="/register" element={<Register />} />
      <Route path="/forgot-password" element={<ForgotPasswordPage />} />
      <Route path="/reset-password" element={<ResetPasswordPage />} />
      <Route path="/verify-email" element={<VerifyEmailPage />} />
      <Route element={<Protected />}>
        <Route element={<AppShell />}>
          <Route index element={<Dashboard />} />
          <Route path="events" element={<RoleOnly roles={['USER', 'APPROVER', 'ADMIN']} />}>
            <Route index element={<UserEventsPage />} />
            <Route path=":slug" element={<EventDetailPage />} />
          </Route>
          <Route path="events/new" element={<RoleOnly roles={['ADMIN']} />}><Route index element={<EventEditorPage />} /></Route>
          <Route path="events/:id/edit" element={<RoleOnly roles={['ADMIN']} />}><Route index element={<EventEditorPage />} /></Route>
          <Route path="admin" element={<RoleOnly roles={['ADMIN']} />}><Route index element={<AdminHomePage />} /></Route>
          <Route path="admin/events" element={<RoleOnly roles={['ADMIN']} />}><Route index element={<EventsPage />} /></Route>
          <Route path="admin/events/:id/participants" element={<RoleOnly roles={['ADMIN']} />}><Route index element={<ParticipantManagerPage />} /></Route>
          <Route path="calendar" element={<CalendarPage />} />
          <Route path="upload" element={<UploadPage />} />
          <Route path="photos" element={<PhotosPage />} />
          <Route path="notifications" element={<NotificationsPage />} />
          <Route path="profile" element={<div className="page-stack"><SectionHeader kicker="Account / profile" title="Your account" description="Profile and privacy controls are managed by your institutional account." /><p>Signed in securely. Use the mobile app or account administrator for display-name changes.</p></div>} />
          <Route path="moderation" element={<RoleOnly roles={['ADMIN', 'APPROVER']} />}><Route index element={<ModerationPage />} /></Route>
          <Route path="review-history" element={<RoleOnly roles={['ADMIN', 'APPROVER']} />}><Route index element={<ReviewHistoryPage />} /></Route>
          <Route path="removal-requests" element={<RoleOnly roles={['ADMIN', 'APPROVER']} />}><Route index element={<RemovalRequestsPage />} /></Route>
          <Route path="content" element={<RoleOnly roles={['ADMIN']} />}><Route index element={<ContentPage />} /></Route>
          <Route path="team" element={<RoleOnly roles={['ADMIN']} />}><Route index element={<TeamPage />} /><Route path=":id/edit" element={<TeamEditorPage />} /></Route>
          <Route path="archives" element={<RoleOnly roles={['ADMIN']} />}><Route index element={<ArchivesPage />} /><Route path=":id" element={<ArchiveManagerPage />} /></Route>
          <Route path="media" element={<RoleOnly roles={['ADMIN']} />}><Route index element={<MediaLibraryPage />} /></Route>
          <Route path="scheduled" element={<RoleOnly roles={['ADMIN']} />}><Route index element={<ScheduledPage />} /></Route>
          <Route path="backup-status" element={<RoleOnly roles={['ADMIN']} />}><Route index element={<BackupStatusPage />} /></Route>
          <Route path="settings" element={<RoleOnly roles={['ADMIN']} />}><Route index element={<SettingsPage />} /></Route>
        </Route>
      </Route>
    </Route>
  </Routes>;
}

createRoot(document.getElementById('root')!).render(<React.StrictMode><BrowserRouter basename="/manage"><RootApp /></BrowserRouter></React.StrictMode>);
